/*
 * EVERY SENTENCE THE RE-CHECKS OF #523 INVENTED OR QUOTED, WITH HOW
 * origin/main READS IT (re-check of #523, round 6). Data only; the tests are
 * tests/amendment-exchange-whitelist.unit.spec.ts.
 *
 * Sources, by `src`:
 *   check5  re-check 5 (recheck5-523/sentences.mts, its own truth labels)
 *   check4  re-check 4 (recheck4-523/sent.ts)
 *   check1  re-check 1 (recheck-523/invent-branch.txt, the sentences saved whole)
 *   pr523   this pull request's earlier tables, and the real record sentences
 * A sentence that appears in more than one table is kept once (by bill type
 * and text), under the first source above that holds it.
 *
 * `truth`, read from the sentence alone: F both chambers now hold one text
 * and the sentence says so; S the exchange between the chambers goes on;
 * N no agreement, or not an exchange sentence; P presented to the President;
 * L law; V veto.
 *
 * `main` is what origin/main f9d21605 reads, computed once on 2026-11-19 by
 * running main's own code on each sentence as a bill's latest action
 * (bill_type as given, last_action_date 2026-11-17, NOW 2026-11-18T18:00Z):
 * [mapStatus, statusKeyFor, passageState stage/passedBy/next,
 *  floorAnsweredChamber, deriveJourney nowKey, decisionState,
 *  statusKeyFor of the same record stored at `committee`].
 */
export type Truth = 'F' | 'S' | 'N' | 'P' | 'L' | 'V';
export type Reading = [string, string, string, string | null, string, string, string];
export interface Sentence {
  id: string;
  src: 'check5' | 'check4' | 'check1' | 'pr523';
  type: string;
  truth: Truth;
  text: string;
  /** The bill's own number, where the sentence names its bill (round 7);
   *  1 otherwise. */
  number?: number;
  main: Reading;
}

